// Generated by npm run build:pwa. Keep each version's app files together.
const CACHE_PREFIX = 'sequencepang2-shell-';
const CACHE_NAME = CACHE_PREFIX + '2738127c90c79b5b';
const ASSETS = [
  "./app.js",
  "./audio.js",
  "./campaign-data.js",
  "./drag-hit.js",
  "./encore-data.js",
  "./engine.js",
  "./expansion-data.js",
  "./fonts/jua.woff",
  "./fonts/outfit.woff",
  "./hint-data.js",
  "./hints.js",
  "./icons/apple-touch-icon.png",
  "./icons/favicon-48.png",
  "./icons/icon-192.png",
  "./icons/icon-512.png",
  "./icons/maskable-512.png",
  "./index.html",
  "./levels.js",
  "./mango-v2.png",
  "./manifest.webmanifest",
  "./progress.js",
  "./pwa.js",
  "./release.js",
  "./sequencepang2-logo-v2.jpg",
  "./session.js",
  "./style.css"
];
const AUDIO_CACHE = CACHE_NAME + '-audio';
const AUDIO_ASSETS = [
  "./audio/jingles/03_stage_clear.wav",
  "./audio/jingles/04_gentle_retry.wav",
  "./audio/jingles/05_all_stars_complete.wav",
  "./audio/music/01_mango_garden_menu.ogg",
  "./audio/music/01_mango_garden_menu.wav",
  "./audio/music/02_constellation_path_play.ogg",
  "./audio/music/02_constellation_path_play.wav",
  "./audio/sfx/invalid_soft.wav",
  "./audio/sfx/mango_hint.wav",
  "./audio/sfx/select_1.wav",
  "./audio/sfx/select_2.wav",
  "./audio/sfx/select_3.wav",
  "./audio/sfx/select_4.wav",
  "./audio/sfx/select_5.wav",
  "./audio/sfx/sequence_pop.wav",
  "./audio/sfx/star_collect.wav",
  "./audio/sfx/ui_tap.wav"
];
const BASE = new URL('./', self.location.href);
const AUDIO_URLS = new Set(AUDIO_ASSETS.map(path => new URL(path, BASE).href));
const ASSET_URLS = new Set(ASSETS.map(path => new URL(path, BASE).href));

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    try {
      const cache = await caches.open(CACHE_NAME);
      await cache.addAll(ASSETS.map(path => new Request(new URL(path, BASE), { cache: 'reload' })));
    } catch (error) {
      await caches.delete(CACHE_NAME);
      throw error;
    }
  })());
  // Updates wait until all old tabs close or the player chooses the home button.
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith(CACHE_PREFIX) && key !== CACHE_NAME && key !== AUDIO_CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('message', event => {
  if (event.data?.type === 'ACTIVATE_UPDATE') event.waitUntil(self.skipWaiting());
});

self.addEventListener('fetch', event => {
  if (event.request.method !== 'GET') return;
  const url = new URL(event.request.url);
  if (url.origin !== BASE.origin) return;
  url.search = '';
  const isHome = url.pathname === BASE.pathname || url.href === new URL('index.html', BASE).href;
  const key = isHome && event.request.mode === 'navigate' ? new URL('index.html', BASE).href : url.href;
  if (AUDIO_URLS.has(key)) {
    // Optional audio is saved only as it is used, never a prerequisite for the
    // offline game install. A quota/network failure must not break the game.
    event.respondWith((async () => {
      let cache;
      try { cache = await caches.open(AUDIO_CACHE); const saved = await cache.match(key); if (saved) return saved; } catch {}
      const response = await fetch(event.request);
      if (response.ok && cache) { try { await cache.put(key, response.clone()); } catch {} }
      return response;
    })());
    return;
  }
  if (!ASSET_URLS.has(key)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE_NAME);
    return await cache.match(key) || fetch(event.request);
  })());
});
